class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        adj_list = defaultdict(list)
        for a, b in edges:
            adj_list[a].append(b)
            adj_list[b].append(a)

        @lru_cache(maxsize=None)
        def dp(i, floors):
            c = coins[i] >> floors
            no_floor = c - k
            floor_val = c // 2

            # Base case: if node has no children, return the best option
            if not adj_list[i]:
                return max(no_floor, floor_val)

            # Initialize with floor option as base
            max_points = floor_val

            # For each child, calculate points for both choices
            for e in adj_list[i]:
                child_no_floor = dp(e, floors)
                child_floor = dp(e, floors + 1)

                # Add to respective totals
                no_floor += child_no_floor
                floor_val += child_floor

                # Update maximum points
                max_points = max(max_points, no_floor, floor_val)

            return max_points

        return dp(0, 0)

