            left = f0
        else:
            left = f1

        # Determine a1 based on whether k is even or odd
        if k % 2 == 0:
            a1 = (n - 2) * r
        else:
            a1 = (n - 2) * (n - 1) * r

        # Calculate q
        q = (n - 1) ** 2

        # Calculate ans based on whether q equals 1
        if q == 1:
            ans = (a1 * (k // 2) + left) % mod
        else:
            ans = a1 * pow(q, k // 2, mod) % mod + left
            ans %= mod

        return ans % mod

